    private fun addEntry(res: MutableMap<Key, Entry>, gender: Int, parameter: Double, sdMap: Entry) {
        res[Key(gender, parameter.toFloat())] = sdMap
    }

    private fun newSDMap(
        sd3neg: Float,
        sd2neg: Float,
        sd1neg: Float,
        sd0: Float,
        sd1: Float,
        sd2: Float,
        sd3: Float
    ): Entry {
        val sdMap = mapOf(
            sd3neg to 3,
            sd2neg to 2,
            sd1neg to 1,
            sd0 to 0,
            sd1 to 1,
            sd2 to 2,
            sd3 to 3)
        val list: Set<Float> = sdMap.keys
        return Entry(sdMap, list.min(), list.max(), list.sorted())
    }
